const fmtDate = (date?: string) => date ? new Date(date).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' }) : '—';
const roleName: Record<string, string> = { MANAGER: 'Gestor', DISPATCHER: 'Despachante', DRIVER: 'Motorista', SALES_REP: 'Vendedor' };

export function OverviewView({ orders, vehicles, routes, config, user, onNavigate }: {
  orders: Order[]; vehicles: Vehicle[]; routes: Route[]; config: Config; user: User; onNavigate: (tab: string) => void
}) {
  const pending = orders.filter(o => ['pendente','pendente_complemento','reagendado_d1','bloqueio_fiscal'].includes(o.status));
  const transit = orders.filter(o => ['em_rota','alocado_no_bau'].includes(o.status));
  const delivered = orders.filter(o => ['entregue','entregue_parcial'].includes(o.status));
  const incidents = orders.filter(o => ['ocorrencia','bloqueio_fiscal'].includes(o.status));
  const occupancy = vehicles.length ? vehicles.reduce((s,v) => s + ((v.currentWeightKg / Math.max(1,v.maxWeightKg)) * 100 + (v.currentVolumeM3 / Math.max(1,v.maxVolumeM3)) * 100) / 2, 0) / vehicles.length : 0;
  const redeliveryCost = (config.redeliveryDistanceKm / config.avgFuelEfficiencyKmL) * config.dieselPricePerLiter + config.redeliveryFixedTimeHours * config.crewHourlyRate;
  const estimatedExposure = incidents.filter(o => o.status === 'ocorrencia').length * redeliveryCost;
  const bars = [
    { label: 'Fila', value: pending.length },
    { label: 'Carga', value: orders.filter(o => o.status === 'alocado_no_bau').length },
    { label: 'Em rota', value: orders.filter(o => o.status === 'em_rota').length },
    { label: 'Entregue', value: delivered.length },
    { label: 'Exceção', value: incidents.length }
  ];
  const maxBar = Math.max(1, ...bars.map(b => b.value));
  return <div className="lm-page-stack">
    <div className="lm-page-heading"><div><span className="lm-eyebrow">PAINEL DO PROPRIETÁRIO</span><h1>Bom dia, {user.name.split(' ')[0]}.</h1><p>Visão geral da operação, desempenho da frota e pontos que exigem decisão.</p></div><div className="lm-heading-actions"><span className="lm-live-indicator"><i/> Dados atualizados</span><button className="lm-secondary-button" onClick={() => onNavigate('dispatch')}><Zap size={15}/> Abrir despacho</button></div></div>
    <div className="lm-kpi-grid">
      <Kpi icon={<Package/>} label="Pedidos na fila" value={pending.length} note={`${orders.length} pedidos cadastrados`} tone="blue" />
      <Kpi icon={<Navigation/>} label="Em operação" value={transit.length} note={`${routes.filter(r => r.status === 'em_rota').length} rotas em andamento`} tone="green" />
      <Kpi icon={<CheckCircle2/>} label="Entregas concluídas" value={delivered.length} note={`${orders.length ? Math.round(delivered.length/orders.length*100) : 0}% dos pedidos`} tone="teal" />
      <Kpi icon={<Gauge/>} label="Ocupação média" value={`${number(occupancy)}%`} note="Peso e cubagem combinados" tone="amber" />
    </div>
    <div className="lm-overview-grid">
      <section className="lm-panel lm-performance-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">CAPACIDADE OPERACIONAL</span><h3>Utilização da frota</h3></div><button className="lm-text-button" onClick={() => onNavigate('fleet')}>Ver frota <ChevronRight size={14}/></button></div>
        <div className="lm-fleet-summary"><div><strong>{vehicles.filter(v=>v.status !== 'manutencao').length}</strong><span>veículos ativos</span></div><div><strong>{vehicles.filter(v=>v.status === 'disponivel').length}</strong><span>disponíveis</span></div><div><strong>{vehicles.filter(v=>v.status === 'manutencao').length}</strong><span>em manutenção</span></div></div>
        <div className="lm-vehicle-bars">{vehicles.slice(0,5).map(v => <div key={v.id} className="lm-vehicle-bar-row"><div><b>{v.name || v.plate}</b><span>{v.plate} · {v.driverName || 'Sem motorista'}</span></div><div className="lm-dual-bars"><div className="lm-progress"><i style={{width:`${Math.min(100,v.currentWeightKg/Math.max(1,v.maxWeightKg)*100)}%`}}/></div><div className="lm-progress lm-progress-muted"><i style={{width:`${Math.min(100,v.currentVolumeM3/Math.max(1,v.maxVolumeM3)*100)}%`}}/></div></div><strong>{number(v.currentWeightKg/Math.max(1,v.maxWeightKg)*100)}%</strong></div>)}</div>
        <div className="lm-legend"><span><i className="lm-legend-weight"/> Peso</span><span><i className="lm-legend-volume"/> Cubagem</span><small>Limite operacional: {config.maxVehicleUtilizationPct}%</small></div>
      </section>
      <section className="lm-panel lm-chart-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">RITMO DA OPERAÇÃO</span><h3>Distribuição dos pedidos</h3></div><span className="lm-subtle-tag">Situação atual</span></div><div className="lm-chart"><div className="lm-chart-grid"><i/><i/><i/><i/></div><div className="lm-chart-bars">{bars.map(b=><div key={b.label}><div className="lm-chart-bar" style={{height:`${Math.max(4,b.value/maxBar*100)}%`}}><span>{b.value}</span></div><small>{b.label}</small></div>)}</div></div><div className="lm-chart-foot"><span><i/> pedidos por etapa</span><b>{orders.length} cadastrados</b></div></section>
    </div>
    <div className="lm-overview-grid lm-overview-bottom">
      <section className="lm-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">ATENÇÃO OPERACIONAL</span><h3>Fila de exceções</h3></div><span className={`lm-count-pill ${incidents.length ? 'is-warning' : ''}`}>{incidents.length}</span></div>
        {incidents.length ? <div className="lm-exception-list">{incidents.slice(0,4).map(o=><div key={o.id}><span className="lm-exception-icon"><AlertTriangle size={16}/></span><div><b>{o.tradeName}</b><small>NF {o.nfe || '—'} · {statusLabel(o.status)}</small></div><button onClick={()=>onNavigate('orders')}>Ver <ChevronRight size={13}/></button></div>)}</div> : <div className="lm-empty-inline"><CheckCircle2 size={20}/> Nenhuma exceção operacional pendente.</div>}
      </section>
      <section className="lm-panel lm-cost-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">CUSTO LOGÍSTICO</span><h3>Exposição estimada com reentregas</h3></div><Fuel size={18}/></div><strong className="lm-cost-value">{brl(estimatedExposure)}</strong><p>Base calculada a partir de {incidents.filter(o=>o.status==='ocorrencia').length} ocorrência(s) e custo padrão de {brl(redeliveryCost)} por reentrega.</p><div className="lm-cost-equation">(distância ÷ consumo × diesel) + (tempo × equipe)</div><button className="lm-text-button" onClick={()=>onNavigate('settings')}>Revisar parâmetros de custo <ArrowRight size={14}/></button></section>
    </div>
    <div className="lm-quick-actions"><button onClick={()=>onNavigate('orders')}><Plus/> Novo pedido</button><button onClick={()=>onNavigate('dispatch')}><Zap/> Otimizar carregamento</button><button onClick={()=>onNavigate('map')}><MapPin/> Ver mapa operacional</button><button onClick={()=>onNavigate('integrations')}><FileInput/> Integrações</button></div>
  </div>;
}

function Kpi({icon,label,value,note,tone}:{icon:React.ReactNode;label:string;value:React.ReactNode;note:string;tone:string}) {
  return <div className={`lm-kpi lm-kpi-${tone}`}><div className="lm-kpi-top"><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><small>{note}</small></div>;
}

const blankOrder = { nfe:'', customerName:'', cnpj:'', address:'', neighborhood:'', city:'Salvador', state:'BA', weightKg:'', volumeM3:'', totalValue:'', timeWindow:'08:00–17:00', lat:'', lng:'', notes:'' };
function csvCell(value: string) { return `"${String(value ?? '').replaceAll('"','""')}"`; }
function parseCsv(text: string): any[] {
  const first = text.split(/\r?\n/,1)[0] || '';
  const delimiter = first.includes(';') ? ';' : ',';
  const rows: string[][] = []; let row: string[] = [], cell = '', quote = false;
  for (let i=0;i<text.length;i++) { const ch=text[i]; if (ch==='"' && text[i+1]==='"' && quote) { cell+='"'; i++; }
    else if (ch==='"') quote=!quote; else if (ch===delimiter && !quote) { row.push(cell); cell=''; }
    else if ((ch==='\n'||ch==='\r')&&!quote) { if (ch==='\r'&&text[i+1]==='\n')i++; row.push(cell); if(row.some(v=>v.trim()))rows.push(row); row=[];cell=''; }
    else cell+=ch; }
  row.push(cell); if(row.some(v=>v.trim()))rows.push(row);
  const headers=(rows.shift()||[]).map(h=>h.trim().toLowerCase().replace(/[\s_-]+/g,''));
  const aliases: Record<string,string> = { nota:'nfe',nfe:'nfe',nf:'nfe',cliente:'customerName',razaosocial:'customerName',nome:'customerName',cnpj:'cnpj',endereco:'address',logradouro:'address',bairro:'neighborhood',cidade:'city',estado:'state',peso:'weightKg',pesokg:'weightKg',weightkg:'weightKg',cubagem:'volumeM3',volume:'volumeM3',volumem3:'volumeM3',valor:'totalValue',valorpedido:'totalValue',totalvalue:'totalValue',janela:'timeWindow',timewindow:'timeWindow',lat:'lat',latitude:'lat',lng:'lng',longitude:'lng' };
  return rows.map(values => {
    const item:any={}; values.forEach((v,i)=>{const key=aliases[headers[i]]||headers[i];item[key]=v?.trim()||'';});
    for (const key of ['weightKg','volumeM3','totalValue','lat','lng']) if(item[key]) item[key]=Number(String(item[key]).replace(',','.'));
    return item;
  });
}
function parseNfeXml(xml: string): any[] {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  if (doc.querySelector('parsererror')) throw new Error('O XML não parece ser uma NF-e válida.');
  const text = (selector: string, root: ParentNode = doc) => root.querySelector(selector)?.textContent?.trim() || '';
  const items = Array.from(doc.querySelectorAll('det')).map(det => {
    const prod = det.querySelector('prod'); const rastro = det.querySelector('rastro');
    return { code: text('cProd',prod||doc), name: text('xProd',prod||doc), quantity: Number(text('qCom',prod||doc)||0),
      unitPrice: Number(text('vUnCom',prod||doc)||0), totalPrice: Number(text('vProd',prod||doc)||0),
      lotNumber: text('nLote',rastro||doc), expiryDate: text('dVal',rastro||doc) };
  });
  const dest = doc.querySelector('dest'); const addr = dest?.querySelector('enderDest');
  const peso = Number(text('pesoB',doc.querySelector('vol')||doc)||0);
  return [{ nfe:text('nNF'), customerName:text('xNome',dest||doc), cnpj:text('CNPJ',dest||doc)||text('CPF',dest||doc),
    address:[text('xLgr',addr||doc),text('nro',addr||doc),text('xCpl',addr||doc)].filter(Boolean).join(', '),
    neighborhood:text('xBairro',addr||doc),city:text('xMun',addr||doc),state:text('UF',addr||doc),cep:text('CEP',addr||doc),
    weightKg:peso, volumeM3:0, totalValue:Number(text('vNF',doc.querySelector('ICMSTot')||doc)||0), items, source:'xml_nfe' }];
}

export function OrdersView({ orders, onRefresh, onToast, canEdit }: { orders: Order[]; onRefresh:()=>Promise<void>; onToast:(s:string)=>void; canEdit:boolean }) {
  const [search,setSearch]=useState(''); const [filter,setFilter]=useState('todos'); const [showForm,setShowForm]=useState(false); const [editing,setEditing]=useState<Order|null>(null); const [form,setForm]=useState<any>(blankOrder); const [busy,setBusy]=useState(false); const fileRef=useRef<HTMLInputElement>(null); const invoicePdfRef=useRef<HTMLInputElement>(null); const [invoiceTarget,setInvoiceTarget]=useState<Order|null>(null);
  const shown=orders.filter(o=>(filter==='todos'||o.status===filter)&&`${o.nfe} ${o.tradeName} ${o.address} ${o.neighborhood}`.toLowerCase().includes(search.toLowerCase()));
  const createNew=()=>{setEditing(null);setForm(blankOrder);setShowForm(true);};
  const editOrder=(o:Order)=>{setEditing(o);setForm({...blankOrder,...o,weightKg:String(o.weightKg||''),volumeM3:String(o.volumeM3||''),totalValue:String(o.totalValue||''),lat:String(o.lat??''),lng:String(o.lng??'')});setShowForm(true);};
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{const data={...form,weightKg:Number(form.weightKg)||0,volumeM3:Number(form.volumeM3)||0,totalValue:Number(form.totalValue)||0,lat:form.lat===''?null:Number(form.lat),lng:form.lng===''?null:Number(form.lng),tradeName:form.customerName};
    if(editing) await patch(`/orders/${editing.id}`,data); else await post('/orders',data); await onRefresh();setShowForm(false);onToast(editing?'Pedido atualizado.':'Pedido cadastrado.');}catch(err){onToast(err instanceof Error?err.message:'Erro ao salvar pedido.');}finally{setBusy(false);}};
  const importFile=async(file?:File)=>{if(!file)return;setBusy(true);try{const raw=await file.text();let rows:any[]=[];if(file.name.toLowerCase().endsWith('.xml'))rows=parseNfeXml(raw);else if(file.name.toLowerCase().endsWith('.json')){const v=JSON.parse(raw);rows=Array.isArray(v)?v:(v.orders||[v]);}else rows=parseCsv(raw);const result=await post<{imported:number}>('/orders/bulk-import',{orders:rows});await onRefresh();onToast(`${result.imported} pedido(s) importado(s). Dados incompletos foram para a quarentena.`);}catch(err){onToast(err instanceof Error?err.message:'Falha na importação.');}finally{setBusy(false);if(fileRef.current)fileRef.current.value='';}};
  const uploadInvoicePdf=async(file?:File)=>{if(!file||!invoiceTarget)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){onToast('Selecione um arquivo PDF da DANFE/NF-e.');return;}if(file.size>8*1024*1024){onToast('O PDF deve ter no máximo 8 MB.');return;}setBusy(true);try{const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Não foi possível ler o PDF.'));reader.readAsDataURL(file);});await post(`/orders/${invoiceTarget.id}/invoice-pdf`,{filename:file.name,dataUrl});await onRefresh();onToast(`PDF da NF-e ${invoiceTarget.nfe||''} anexado e disponível para o motorista.`);}catch(err){onToast(err instanceof Error?err.message:'Falha ao anexar o PDF.');}finally{setBusy(false);setInvoiceTarget(null);if(invoicePdfRef.current)invoicePdfRef.current.value='';}};
  const template=()=>{const content='nfe;customerName;cnpj;address;neighborhood;city;state;weightKg;volumeM3;totalValue;timeWindow;lat;lng\n10456;Mercadinho Exemplo;00000000000100;Rua Exemplo 100;Pituba;Salvador;BA;350;2.4;2800;08:00-12:00;;;';const blob=new Blob([content],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='modelo-importacao-logisticmaster.csv';a.click();URL.revokeObjectURL(url);};
  return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">GESTÃO DE PEDIDOS</span><h1>Pedidos</h1><p>Receba pedidos de qualquer sistema, valide os dados e prepare a expedição.</p></div><div className="lm-heading-actions"><input ref={fileRef} type="file" accept=".csv,.xml,.json,application/xml,text/csv,application/json" hidden onChange={e=>importFile(e.target.files?.[0])}/><input ref={invoicePdfRef} type="file" accept="application/pdf,.pdf" hidden onChange={e=>uploadInvoicePdf(e.target.files?.[0])}/><button className="lm-secondary-button" onClick={template}><FileDown size={15}/> Modelo CSV</button><button className="lm-secondary-button" onClick={()=>fileRef.current?.click()} disabled={busy}><Upload size={15}/> Importar dados</button>{canEdit&&<button className="lm-primary-button" onClick={createNew}><Plus size={16}/> Novo pedido</button>}</div></div>
    <div className="lm-list-toolbar"><div className="lm-search"><Search size={16}/><input placeholder="Buscar por NF, cliente ou endereço..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="todos">Todos os status</option>{['pendente_complemento','bloqueio_fiscal','pendente','alocado_no_bau','em_rota','entregue','entregue_parcial','ocorrencia','reagendado_d1'].map(s=><option key={s} value={s}>{statusLabel(s)}</option>)}</select><span className="lm-result-count">{shown.length} pedido(s)</span></div>
    <div className="lm-table-wrap"><table className="lm-table"><thead><tr><th>Pedido / NF-e</th><th>Cliente</th><th>Destino</th><th>Carga</th><th>Janela</th><th>Status</th><th></th></tr></thead><tbody>{shown.map(o=><tr key={o.id}><td><b className="lm-mono">#{o.nfe||o.id.slice(0,8)}</b><small>{o.items?.length||0} item(ns)</small></td><td><b>{o.tradeName}</b><small>{o.cnpj||'CNPJ não informado'}</small></td><td><span>{o.neighborhood||o.city||'—'}</span><small>{o.address}</small></td><td><b>{number(o.weightKg)} kg</b><small>{number(o.volumeM3)} m³</small></td><td>{o.timeWindow||'08:00–17:00'}</td><td><Status status={o.status}/></td><td><div className="lm-inline-actions">{canEdit&&<button className={`lm-icon-button ${o.nfePdfAvailable?'is-pdf-ready':''}`} onClick={()=>{setInvoiceTarget(o);invoicePdfRef.current?.click();}} title={o.nfePdfAvailable?'Substituir PDF da NF-e':'Anexar DANFE em PDF'}>{o.nfePdfAvailable?<FileText size={16}/>:<FileUp size={16}/>}</button>}<button className="lm-icon-button" onClick={()=>editOrder(o)} title="Ver / editar pedido"><ChevronRight size={17}/></button></div></td></tr>)}</tbody></table>{!shown.length&&<div className="lm-empty-state"><Package size={24}/><b>Nenhum pedido encontrado</b><span>Importe um arquivo ou cadastre o primeiro pedido.</span></div>}</div>
    <div className="lm-import-note"><FileInput size={17}/><div><b>Entrada facilitada para outros sistemas</b><span>Importe CSV, JSON ou XML de NF-e. Para integração automática, gere uma API key na área Integrações e envie pedidos para <code>POST /api/integrations/orders</code>.</span></div></div>
    {showForm&&<div className="lm-modal-backdrop"><form className="lm-modal lm-modal-wide" onSubmit={submit}><div className="lm-modal-head"><div><span className="lm-eyebrow">{editing?'ATUALIZAÇÃO':'NOVA ENTRADA'}</span><h2>{editing?'Complementar pedido':'Cadastrar pedido'}</h2></div><button type="button" className="lm-icon-button" onClick={()=>setShowForm(false)}><X/></button></div><div className="lm-form-grid"><Field label="Cliente / razão social" value={form.customerName} onChange={(v:any)=>setForm({...form,customerName:v})} required/><Field label="Número da NF-e" value={form.nfe} onChange={(v:any)=>setForm({...form,nfe:v})}/><Field label="CNPJ" value={form.cnpj} onChange={(v:any)=>setForm({...form,cnpj:v})}/><Field label="Endereço de entrega" value={form.address} onChange={(v:any)=>setForm({...form,address:v})} required wide/><Field label="Bairro" value={form.neighborhood} onChange={(v:any)=>setForm({...form,neighborhood:v})}/><Field label="Cidade" value={form.city} onChange={(v:any)=>setForm({...form,city:v})}/><Field label="Peso total (kg)" type="number" value={form.weightKg} onChange={(v:any)=>setForm({...form,weightKg:v})} required/><Field label="Cubagem total (m³)" type="number" value={form.volumeM3} onChange={(v:any)=>setForm({...form,volumeM3:v})} required/><Field label="Valor da nota (opcional)" type="number" value={form.totalValue} onChange={(v:any)=>setForm({...form,totalValue:v})}/><Field label="Janela de entrega" value={form.timeWindow} onChange={(v:any)=>setForm({...form,timeWindow:v})}/><Field label="Latitude (opcional)" value={form.lat} onChange={(v:any)=>setForm({...form,lat:v})}/><Field label="Longitude (opcional)" value={form.lng} onChange={(v:any)=>setForm({...form,lng:v})}/></div><p className="lm-form-helper">O sistema pode tentar localizar o endereço após o cadastro. Pedido sem peso, cubagem ou endereço fica na fila de complementação.</p><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setShowForm(false)}>Cancelar</button><button className="lm-primary-button" disabled={busy}>{busy?'Salvando…':editing?'Salvar alterações':'Adicionar à fila de pedidos'}</button></div></form></div>}
  </div>;
}

function Field({label,value,onChange,type='text',required=false,wide=false}:{label:string;value:any;onChange:(v:string)=>void;type?:string;required?:boolean;wide?:boolean}) {return <label className={`lm-field ${wide?'lm-field-wide':''}`}><span>{label}</span><input type={type} value={value??''} onChange={e=>onChange(e.target.value)} required={required} step={type==='number'?'any':undefined}/></label>}
function Status({status}:{status:string}) {const warn=['bloqueio_fiscal','ocorrencia','pendente_complemento'].includes(status);const good=['entregue','entregue_parcial'].includes(status);return <span className={`lm-status ${warn?'is-warning':good?'is-good':status==='em_rota'?'is-blue':''}`}><i/>{statusLabel(status)}</span>}

export function FleetView({vehicles,onRefresh,onToast,canEdit}:{vehicles:Vehicle[];onRefresh:()=>Promise<void>;onToast:(s:string)=>void;canEdit:boolean}) {
  const [show,setShow]=useState(false);const [form,setForm]=useState({name:'',model:'',plate:'',driverName:'',driverPhone:'',maxWeightKg:'1500',maxVolumeM3:'8',fuelConsumptionKmL:'8'});const [busy,setBusy]=useState(false);
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await post('/vehicles',{...form,maxWeightKg:Number(form.maxWeightKg),maxVolumeM3:Number(form.maxVolumeM3),fuelConsumptionKmL:Number(form.fuelConsumptionKmL)});await onRefresh();setShow(false);onToast('Veículo cadastrado.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao cadastrar veículo.');}finally{setBusy(false);}};
  const update=async(v:Vehicle,status:string)=>{try{await patch(`/vehicles/${v.id}`,{status});await onRefresh();onToast('Disponibilidade atualizada.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao atualizar veículo.');}};
  return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">CAPACIDADE E DISPONIBILIDADE</span><h1>Frota</h1><p>Cadastre veículos, capacidades físicas e motoristas responsáveis.</p></div>{canEdit&&<button className="lm-primary-button" onClick={()=>setShow(true)}><Plus size={16}/> Novo veículo</button>}</div><div className="lm-fleet-cards">{vehicles.map(v=>{const wp=v.currentWeightKg/Math.max(v.maxWeightKg,1)*100;const vp=v.currentVolumeM3/Math.max(v.maxVolumeM3,1)*100;return <div className="lm-panel lm-fleet-card" key={v.id}><div className="lm-fleet-card-head"><span className="lm-fleet-truck-icon"><Truck size={20}/></span><Status status={v.status}/><button className="lm-icon-button" title="Alterar status" onClick={()=>update(v,v.status==='manutencao'?'disponivel':'manutencao')}>{v.status==='manutencao'?<RefreshCw size={15}/>:<ShieldAlert size={15}/>}</button></div><h3>{v.name||v.model}</h3><div className="lm-fleet-plate">{v.plate}</div><div className="lm-fleet-driver"><Users size={14}/>{v.driverName||'Motorista não vinculado'}</div><div className="lm-capacity-line"><div><span>Peso carregado</span><b>{number(v.currentWeightKg)} / {number(v.maxWeightKg)} kg</b></div><div className="lm-progress"><i style={{width:`${Math.min(wp,100)}%`}}/></div></div><div className="lm-capacity-line"><div><span>Cubagem ocupada</span><b>{number(v.currentVolumeM3)} / {number(v.maxVolumeM3)} m³</b></div><div className="lm-progress lm-progress-muted"><i style={{width:`${Math.min(vp,100)}%`}}/></div></div><div className="lm-fleet-card-foot"><span><Fuel size={13}/> {v.fuelConsumptionKmL||'—'} km/L</span><span>{(v.allocatedOrders||[]).length} pedido(s) no baú</span></div></div>})}</div>{show&&<div className="lm-modal-backdrop"><form className="lm-modal" onSubmit={submit}><div className="lm-modal-head"><div><span className="lm-eyebrow">CADASTRO DE FROTA</span><h2>Novo veículo</h2></div><button className="lm-icon-button" type="button" onClick={()=>setShow(false)}><X/></button></div><div className="lm-form-grid"><Field label="Identificação" value={form.name} onChange={v=>setForm({...form,name:v})}/><Field label="Modelo" value={form.model} onChange={v=>setForm({...form,model:v})}/><Field label="Placa" value={form.plate} onChange={v=>setForm({...form,plate:v.toUpperCase()})} required/><Field label="Motorista" value={form.driverName} onChange={v=>setForm({...form,driverName:v})}/><Field label="Telefone do motorista" value={form.driverPhone} onChange={v=>setForm({...form,driverPhone:v})}/><Field label="Capacidade (kg)" type="number" value={form.maxWeightKg} onChange={v=>setForm({...form,maxWeightKg:v})} required/><Field label="Cubagem (m³)" type="number" value={form.maxVolumeM3} onChange={v=>setForm({...form,maxVolumeM3:v})} required/><Field label="Consumo médio (km/L)" type="number" value={form.fuelConsumptionKmL} onChange={v=>setForm({...form,fuelConsumptionKmL:v})}/></div><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setShow(false)}>Cancelar</button><button className="lm-primary-button" disabled={busy}>{busy?'Salvando…':'Salvar veículo'}</button></div></form></div>}</div>;
}

export function CustomersView({customers,onRefresh,onToast,canEdit}:{customers:Retailer[];onRefresh:()=>Promise<void>;onToast:(s:string)=>void;canEdit:boolean}) {
 const [show,setShow]=useState(false);const [form,setForm]=useState({tradeName:'',cnpj:'',address:'',neighborhood:'',city:'Salvador',lat:'',lng:''});const [busy,setBusy]=useState(false);
 const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await post('/customers',{...form,lat:form.lat?Number(form.lat):null,lng:form.lng?Number(form.lng):null});await onRefresh();setShow(false);setForm({tradeName:'',cnpj:'',address:'',neighborhood:'',city:'Salvador',lat:'',lng:''});onToast('Cliente cadastrado.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao salvar cliente.');}finally{setBusy(false);}};
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">DESTINOS E PONTOS DE ENTREGA</span><h1>Clientes</h1><p>Base de endereços, geolocalização e histórico operacional dos estabelecimentos.</p></div>{canEdit&&<button className="lm-primary-button" onClick={()=>setShow(true)}><Plus size={16}/> Novo cliente</button>}</div><div className="lm-customer-grid">{customers.map(c=><div className="lm-panel lm-customer-card" key={c.id}><div className="lm-customer-avatar">{c.tradeName.slice(0,1).toUpperCase()}</div><div className="lm-customer-main"><h3>{c.tradeName}</h3><span>{c.cnpj||'CNPJ não informado'}</span><p><MapPin size={13}/>{c.address}{c.neighborhood?`, ${c.neighborhood}`:''}</p></div><div className="lm-customer-stats"><b>{c.completedDeliveriesCount||0}</b><small>entregas</small><b>{c.avgUnloadMinutes||15} min</b><small>descarga média</small></div></div>)}</div>{!customers.length&&<div className="lm-empty-state"><Users size={24}/><b>Base de clientes vazia</b><span>Cadastre manualmente ou importe pedidos para alimentar a base automaticamente.</span></div>}{show&&<div className="lm-modal-backdrop"><form className="lm-modal" onSubmit={save}><div className="lm-modal-head"><div><span className="lm-eyebrow">NOVO DESTINO</span><h2>Cadastrar cliente</h2></div><button type="button" className="lm-icon-button" onClick={()=>setShow(false)}><X/></button></div><div className="lm-form-grid"><Field label="Nome fantasia / razão social" value={form.tradeName} onChange={v=>setForm({...form,tradeName:v})} required wide/><Field label="CNPJ" value={form.cnpj} onChange={v=>setForm({...form,cnpj:v})}/><Field label="Endereço" value={form.address} onChange={v=>setForm({...form,address:v})} required wide/><Field label="Bairro" value={form.neighborhood} onChange={v=>setForm({...form,neighborhood:v})}/><Field label="Cidade" value={form.city} onChange={v=>setForm({...form,city:v})}/><Field label="Latitude" value={form.lat} onChange={v=>setForm({...form,lat:v})}/><Field label="Longitude" value={form.lng} onChange={v=>setForm({...form,lng:v})}/></div><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setShow(false)}>Cancelar</button><button className="lm-primary-button" disabled={busy}>{busy?'Salvando…':'Salvar cliente'}</button></div></form></div>}</div>;
}

export function DispatchView({orders,vehicles,routes,communications,config,onRefresh,onToast,canOverride}:{orders:Order[];vehicles:Vehicle[];routes:Route[];communications:CommunicationMessage[];config:Config;onRefresh:()=>Promise<void>;onToast:(s:string)=>void;canOverride:boolean}) {
 const [busy,setBusy]=useState(false);const eligible=orders.filter(o=>['pendente','reagendado_d1'].includes(o.status));const loaded=orders.filter(o=>o.status==='alocado_no_bau');
 const optimize=async()=>{setBusy(true);try{const result=await post<{assigned:number;unassigned:any[];routes:Route[]}>('/dispatch/optimize',{});await onRefresh();onToast(`${result.assigned} pedido(s) alocado(s) em ${result.routes.length} rota(s). ${result.unassigned.length?`${result.unassigned.length} sem capacidade.`:''}`);}catch(err){onToast(err instanceof Error?err.message:'Falha na otimização.');}finally{setBusy(false);}};
 const start=async(route:Route)=>{try{await post(`/dispatch/routes/${route.id}/start`,{});await onRefresh();onToast('Rota iniciada. Pedidos enviados para o motorista.');}catch(err){onToast(err instanceof Error?err.message:'Não foi possível iniciar a rota.');}};
 const reverse=async(order:Order,action:string)=>{try{await post(`/dispatch/reverse-checkin/${order.id}`,{action});await onRefresh();onToast('Conferência reversa registrada.');}catch(err){onToast(err instanceof Error?err.message:'Falha no check-in.');}};
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">PN-02 · ALOCAÇÃO E ESTIVAGEM</span><h1>Central de despacho</h1><p>Distribua pedidos por capacidade física e organize a sequência reversa de carregamento.</p></div><button disabled={busy||!eligible.length} className="lm-primary-button" onClick={optimize}><Zap size={16}/>{busy?'Calculando…':'Otimizar carregamento'}</button></div><div className="lm-dispatch-summary"><div><span>Pedidos aguardando</span><b>{eligible.length}</b></div><div><span>Alocados no baú</span><b>{loaded.length}</b></div><div><span>Veículos disponíveis</span><b>{vehicles.filter(v=>v.status==='disponivel').length}</b></div><div><span>Rotas abertas</span><b>{routes.filter(r=>r.status!=='encerrada').length}</b></div></div>
 <DecisionSimulator orders={orders.filter(o=>['pendente','reagendado_d1'].includes(o.status))} config={config} onRefresh={onRefresh} onToast={onToast} canOverride={canOverride}/><DispatchCommunications messages={communications} onRefresh={onRefresh} onToast={onToast}/><div className="lm-route-grid">{routes.filter(r=>r.status!=='encerrada').map(route=>{const vehicle=vehicles.find(v=>v.id===route.vehicleId);const routeOrders=route.orderIds.map(id=>orders.find(o=>o.id===id)).filter(Boolean) as Order[];return <section className="lm-panel lm-route-card" key={route.id}><div className="lm-route-header"><div className="lm-route-icon"><Truck size={20}/></div><div><h3>{vehicle?.name||vehicle?.plate||'Veículo'}</h3><small>{vehicle?.plate} · {route.driverName||vehicle?.driverName}</small></div><Status status={route.status}/></div><div className="lm-route-metrics"><span><b>{routeOrders.length}</b> paradas</span><span><b>{number(route.totalWeightKg)} kg</b></span><span><b>{number(route.totalVolumeM3)} m³</b></span><span><b>{route.estimatedKm!=null?`${number(route.estimatedKm)} km`:'—'}</b> estimados</span></div><div className="lm-lifo-visual"><div className="lm-lifo-label"><span>PORTA DO BAÚ</span><span>FUNDO / CABINE</span></div><div className="lm-lifo-stops">{routeOrders.map((o,i)=><div key={o.id} className="lm-lifo-stop"><b>{i+1}</b><span>{o.tradeName}</span><small>{o.neighborhood||o.address}</small></div>)}</div></div><div className="lm-route-actions">{route.status==='em_carregamento'?<button className="lm-primary-button" onClick={()=>start(route)}>Confirmar saída <ArrowRight size={14}/></button>:<span className="lm-live-indicator"><i/> Motorista em rota</span>}<a className="lm-text-button" href={`https://www.google.com/maps/dir/${routeOrders.map(o=>encodeURIComponent(o.address)).join('/')}`} target="_blank" rel="noreferrer">Abrir trajeto <ArrowUpRight size={14}/></a></div></section>})}</div>
 {orders.some(o=>['ocorrencia','entregue_parcial','cancelado_em_rota'].includes(o.status))&&<section className="lm-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">LOGÍSTICA REVERSA · PN-06</span><h3>Retorno ao galpão</h3></div><span className="lm-count-pill is-warning">{orders.filter(o=>['ocorrencia','entregue_parcial','cancelado_em_rota'].includes(o.status)).length}</span></div><div className="lm-table-wrap"><table className="lm-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Volume retido</th><th>Ocorrência</th><th>Destino</th></tr></thead><tbody>{orders.filter(o=>['ocorrencia','entregue_parcial','cancelado_em_rota'].includes(o.status)).map(o=><tr key={o.id}><td>#{o.nfe||o.id.slice(0,8)}</td><td>{o.tradeName}</td><td>{number(o.retainedWeightKg??o.weightKg)} kg</td><td>{o.occurrenceReason||statusLabel(o.status)}</td><td><div className="lm-inline-actions"><button className="lm-small-button" onClick={()=>reverse(o,'reagendado_d1')}>Reintegrar D+1</button><button className="lm-small-button lm-small-danger" onClick={()=>reverse(o,'baixa_avaria')}>Baixar avaria</button></div></td></tr>)}</tbody></table></div></section>}
 </div>;
}


function DispatchCommunications({messages,onRefresh,onToast}:{messages:CommunicationMessage[];onRefresh:()=>Promise<void>;onToast:(s:string)=>void}) {
 const [reply,setReply]=useState('');
 const latestDriver=[...messages].reverse().find(m=>m.senderRole==='DRIVER');
 const sendReply=async(message:string)=>{
   if(!latestDriver?.routeId){onToast('Ainda não há atualização de motorista para responder.');return;}
   try{await post('/communications',{routeId:latestDriver.routeId,orderId:latestDriver.orderId,kind:'central_reply',message});setReply('');await onRefresh();onToast('Orientação enviada ao motorista.');}
   catch(err){onToast(err instanceof Error?err.message:'Não foi possível enviar a orientação.');}
 };
 return <section className="lm-panel lm-dispatch-comms"><div className="lm-panel-heading"><div><span className="lm-eyebrow">COMUNICAÇÃO EM ROTA</span><h3>Motoristas e central</h3><p>Confirmações rápidas, dúvidas e orientações do despacho.</p></div><span className="lm-count-pill">{messages.filter(m=>m.senderRole==='DRIVER').length}</span></div><div className="lm-message-feed">{messages.slice(-8).reverse().map(m=><div key={m.id} className={`lm-message-item ${m.senderRole==='DRIVER'?'from-driver':'from-central'}`}><div><b>{m.senderName}</b><small>{new Date(m.createdAt).toLocaleString('pt-BR',{hour:'2-digit',minute:'2-digit'})}{m.orderId?` · Pedido ${m.orderId.slice(0,8)}`:''}</small></div><p>{m.message}</p></div>)}{!messages.length&&<div className="lm-empty-inline"><MessageCircle size={18}/> As atualizações dos motoristas aparecerão aqui.</div>}</div><div className="lm-central-quick-replies"><button type="button" className="lm-small-button" onClick={()=>sendReply('Recebido. Pode seguir a orientação da rota.')}>Recebido, pode seguir</button><button type="button" className="lm-small-button" onClick={()=>sendReply('Aguarde um momento. A central está verificando.')}>Aguarde orientação</button><button type="button" className="lm-small-button" onClick={()=>sendReply('Entendido. Registre a ocorrência com foto e siga as instruções.')}>Registrar ocorrência</button></div><form className="lm-driver-message-form" onSubmit={e=>{e.preventDefault();void sendReply(reply);}}><input value={reply} onChange={e=>setReply(e.target.value)} placeholder="Responder ao motorista…" maxLength={500}/><button className="lm-primary-button" disabled={!reply.trim()||!latestDriver?.routeId}><Send size={15}/> Enviar</button></form></section>;
}

function DecisionSimulator({orders,config,onRefresh,onToast,canOverride}:{orders:Order[];config:Config;onRefresh:()=>Promise<void>;onToast:(s:string)=>void;canOverride:boolean}) {
 const [orderId,setOrderId]=useState(orders[0]?.id||'');
 const selected=orders.find(o=>o.id===orderId)||orders[0];
 const [grossMargin,setGrossMargin]=useState('20');
 const [extraKm,setExtraKm]=useState(String(config.redeliveryDistanceKm));
 const [extraHours,setExtraHours]=useState(String(config.redeliveryFixedTimeHours));
 const [spotFreight,setSpotFreight]=useState('150');
 const [tomorrowCost,setTomorrowCost]=useState('0');
 const [calculation,setCalculation]=useState<any>(null);
 const [busy,setBusy]=useState(false);
 React.useEffect(()=>{if(!orders.some(o=>o.id===orderId)&&orders[0])setOrderId(orders[0].id);},[orders,orderId]);
 React.useEffect(()=>setCalculation(null),[orderId]);
 const payload=()=>({orderId:selected?.id,grossMarginPct:Number(grossMargin),extraKmToday:Number(extraKm),extraHoursToday:Number(extraHours),spotFreightToday:Number(spotFreight),tomorrowIncrementalCost:Number(tomorrowCost)});
 const calculate=async()=>{if(!selected)return;setBusy(true);try{setCalculation(await post('/dispatch/decision',payload()));}catch(err){onToast(err instanceof Error?err.message:'Não foi possível calcular os cenários.');}finally{setBusy(false);}};
 const apply=async(decision:'apply_today'|'apply_tomorrow')=>{if(!selected)return;setBusy(true);try{const result=await post<any>('/dispatch/decision',{...payload(),action:decision});setCalculation(result);await onRefresh();onToast(decision==='apply_tomorrow'?'Pedido reservado para consolidação D+1.':'Decisão registrada: manter pedido na operação de hoje.');}catch(err){onToast(err instanceof Error?err.message:'Não foi possível registrar a decisão.');}finally{setBusy(false);}};
 if(!orders.length)return <section className="lm-panel lm-decision-panel"><div className="lm-empty-inline"><CheckCircle2 size={18}/> A calculadora Hoje vs. Amanhã aparecerá quando houver pedidos pendentes para avaliar.</div></section>;
 return <section className="lm-panel lm-decision-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">PN-03 · MARGEM E CUSTO MARGINAL</span><h3>Decisão: despachar hoje ou consolidar D+1?</h3><p>O backend calcula o custo incremental e compara a margem projetada com o piso configurado.</p></div><span className="lm-subtle-tag">Cálculo determinístico</span></div><div className="lm-decision-form"><label className="lm-field"><span>Pedido excedente</span><select value={selected?.id||''} onChange={e=>setOrderId(e.target.value)}>{orders.map(o=><option value={o.id} key={o.id}>NF {o.nfe||o.id.slice(0,8)} · {o.tradeName}</option>)}</select></label><Field label="Margem bruta estimada do pedido (%)" type="number" value={grossMargin} onChange={v=>{setGrossMargin(v);setCalculation(null);}}/><Field label="Km adicionais hoje" type="number" value={extraKm} onChange={v=>{setExtraKm(v);setCalculation(null);}}/><Field label="Horas extras da equipe" type="number" value={extraHours} onChange={v=>{setExtraHours(v);setCalculation(null);}}/><Field label="Frete avulso hoje (R$)" type="number" value={spotFreight} onChange={v=>{setSpotFreight(v);setCalculation(null);}}/><Field label="Custo incremental amanhã (R$)" type="number" value={tomorrowCost} onChange={v=>{setTomorrowCost(v);setCalculation(null);}}/></div><div className="lm-decision-calculate"><button className="lm-primary-button" type="button" disabled={busy} onClick={calculate}>{busy?'Calculando…':'Calcular cenários'}</button></div>{calculation&&<><div className="lm-decision-output"><div><span>Valor do pedido</span><b>{brl(calculation.orderValue)}</b></div><div><span>Custo extra hoje</span><b>{brl(calculation.todayIncrementalCost)}</b></div><div><span>Margem líquida estimada hoje</span><b className={calculation.marginTodayPct<calculation.minimumMarginPct?'is-negative':'is-positive'}>{number(calculation.marginTodayPct)}%</b></div><div><span>Margem estimada D+1</span><b className={calculation.marginTomorrowPct<calculation.minimumMarginPct?'is-negative':'is-positive'}>{number(calculation.marginTomorrowPct)}%</b></div></div><div className="lm-decision-verdict"><div><span className="lm-eyebrow">RECOMENDAÇÃO DO SISTEMA</span><b>{calculation.recommendation==='tomorrow'?'Consolidar na rota de amanhã':'Pode seguir na operação de hoje'}</b><small>{calculation.recommendationReason || (calculation.recommendation==='tomorrow'?`D+1 apresenta melhor margem após os custos incrementais.`:`Hoje apresenta melhor margem após os custos incrementais.`)}</small></div>{canOverride?<div className="lm-inline-actions"><button className="lm-secondary-button" disabled={busy} onClick={()=>apply('apply_tomorrow')}>Agendar D+1</button><button className="lm-primary-button" disabled={busy} onClick={()=>apply('apply_today')}>{calculation.recommendation==='tomorrow'?'Forçar envio hoje':'Registrar envio hoje'}</button></div>:<small>Somente o perfil Gestor pode registrar ou forçar a decisão financeira.</small>}</div></>}</section>;
}

export function MapView({orders,vehicles,onRefresh,onToast}:{orders:Order[];vehicles:Vehicle[];onRefresh:()=>Promise<void>;onToast:(s:string)=>void}) {
 const [selected,setSelected]=useState<Order|null>(null);const [busy,setBusy]=useState(false);
 const geocode=async(o:Order)=>{setBusy(true);try{const result=await post<{lat:number;lng:number}>('/geocode',{address:o.address,city:o.city||'Salvador',state:o.state||'BA'});await patch(`/orders/${o.id}`,{lat:result.lat,lng:result.lng});await onRefresh();onToast(`Coordenadas atualizadas: ${o.tradeName}.`);}catch(err){onToast(err instanceof Error?err.message:'Não foi possível localizar o endereço.');}finally{setBusy(false);}};
 const points=orders.filter(o=>Number.isFinite(Number(o.lat))&&Number.isFinite(Number(o.lng))&&o.lat!==null&&o.lng!==null);
 const center=(selected?.lat!=null&&selected?.lng!=null?selected:undefined)||points[0];const bbox=center?`${Number(center.lng)-0.015}%2C${Number(center.lat)-0.01}%2C${Number(center.lng)+0.015}%2C${Number(center.lat)+0.01}`:null;
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">GEOLOCALIZAÇÃO E ROTAS</span><h1>Mapa operacional</h1><p>Localize clientes, acompanhe posições capturadas e abra rotas em ferramentas de navegação.</p></div><span className="lm-subtle-tag"><MapPin size={14}/> {points.length} destino(s) georreferenciado(s)</span></div><div className="lm-map-layout"><section className="lm-map-frame">{bbox?<iframe title="Mapa de entregas OpenStreetMap" src={`https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik&marker=${center!.lat}%2C${center!.lng}`} loading="lazy"/>:<div className="lm-map-empty"><MapPin size={30}/><b>Mapa aguardando coordenadas</b><span>Localize os endereços a partir da lista ao lado. A geocodificação depende de conexão com a internet.</span></div>}<div className="lm-map-attribution">© OpenStreetMap contributors</div></section><aside className="lm-panel lm-map-list"><div className="lm-panel-heading"><div><span className="lm-eyebrow">DESTINOS DA OPERAÇÃO</span><h3>Clientes e entregas</h3></div></div><div className="lm-map-items">{orders.filter(o=>!['entregue','entregue_parcial'].includes(o.status)).map(o=><div key={o.id} role="button" tabIndex={0} className={`lm-map-item ${selected?.id===o.id?'is-selected':''}`} onClick={()=>setSelected(o)} onKeyDown={e=>{if(e.key==='Enter')setSelected(o);}}><span className="lm-map-pin"><MapPin size={15}/></span><span><b>{o.tradeName}</b><small>{o.address} · {o.neighborhood||o.city}</small><Status status={o.status}/></span><span className="lm-map-item-actions">{o.lat!=null&&o.lng!=null?<CheckCircle2 size={15}/>:<span role="button" tabIndex={0} onClick={e=>{e.stopPropagation();geocode(o);}} onKeyDown={e=>{if(e.key==='Enter'){e.stopPropagation();geocode(o);}}} aria-label="Localizar endereço">{busy?'…':<Navigation size={14}/>}</span>}</span></div>)}</div></aside></div><div className="lm-location-cards">{vehicles.map(v=><div className="lm-panel lm-location-card" key={v.id}><Truck size={17}/><div><b>{v.name||v.plate}</b><small>{v.currentLocation||'Localização ainda não capturada'}</small></div>{v.lat&&v.lng?<a target="_blank" rel="noreferrer" href={`https://www.google.com/maps?q=${v.lat},${v.lng}`}>Abrir posição <ArrowUpRight size={13}/></a>:<span className="lm-muted">GPS não enviado</span>}</div>)}</div></div>;
}

function Signature({onChange}:{onChange:(data:string)=>void}) {
 const canvas=useRef<HTMLCanvasElement>(null);const drawing=useRef(false);
 const point=(e:React.PointerEvent<HTMLCanvasElement>)=>{const el=canvas.current;if(!el)return;const rect=el.getBoundingClientRect();return {x:(e.clientX-rect.left)*el.width/rect.width,y:(e.clientY-rect.top)*el.height/rect.height};};
 const start=(e:React.PointerEvent<HTMLCanvasElement>)=>{const c=canvas.current;if(!c)return;drawing.current=true;c.setPointerCapture(e.pointerId);const p=point(e)!;const ctx=c.getContext('2d')!;ctx.beginPath();ctx.moveTo(p.x,p.y);};
 const move=(e:React.PointerEvent<HTMLCanvasElement>)=>{if(!drawing.current||!canvas.current)return;const p=point(e)!;const ctx=canvas.current.getContext('2d')!;ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#111827';ctx.lineTo(p.x,p.y);ctx.stroke();};
 const end=()=>{drawing.current=false;if(canvas.current)onChange(canvas.current.toDataURL('image/png'));};
 return <div className="lm-signature"><canvas ref={canvas} width={560} height={150} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end}/><button type="button" onClick={()=>{const c=canvas.current;if(c){c.getContext('2d')?.clearRect(0,0,c.width,c.height);onChange('');}}}>Limpar assinatura</button></div>;
}

export function DriverView({orders,vehicles,communications,user,onRefresh,onToast}:{orders:Order[];vehicles:Vehicle[];communications:CommunicationMessage[];user:User;onRefresh:()=>Promise<void>;onToast:(s:string)=>void}) {
 const vehicle=vehicles.find(v=>(v.driverName||'').trim().toLowerCase()===user.name.trim().toLowerCase());
 const assigned=orders.filter(o=>o.truckId===vehicle?.id&&o.routeId===vehicle?.activeRouteId&&['em_rota','alocado_no_bau','ocorrencia','entregue_parcial','entregue'].includes(o.status)).sort((a,b)=>(a.lifoPosition||99)-(b.lifoPosition||99));
 const [target,setTarget]=useState<Order|null>(null);const [receiver,setReceiver]=useState('');const [doc,setDoc]=useState('');const [signature,setSignature]=useState('');const [mode,setMode]=useState('integral');const [reject,setReject]=useState('');const [photo,setPhoto]=useState('');const [occurrenceTarget,setOccurrenceTarget]=useState<Order|null>(null);const [occurrenceReason,setOccurrenceReason]=useState('');const [occurrencePhoto,setOccurrencePhoto]=useState('');const [busy,setBusy]=useState(false);const [gps,setGps]=useState<{lat:number;lng:number}|null>(null);const [queuedIds,setQueuedIds]=useState<string[]>([]);const [queuedCount,setQueuedCount]=useState(0);const [localMessages,setLocalMessages]=useState<CommunicationMessage[]>([]);const [quickText,setQuickText]=useState('');const [isOnline,setIsOnline]=useState(navigator.onLine);const [invoiceStates,setInvoiceStates]=useState<Record<string,'syncing'|'ready'|'missing'>>({});
 React.useEffect(()=>{const refreshQueue=async()=>{try{const queued=await listMutations();setQueuedCount(queued.length);setQueuedIds(queued.map(m=>m.path.match(/deliveries\/([^/]+)\//)?.[1]).filter(Boolean) as string[]);}catch{}};refreshQueue();window.addEventListener('online',refreshQueue);const timer=window.setInterval(refreshQueue,3000);return()=>{window.removeEventListener('online',refreshQueue);window.clearInterval(timer);};},[]);
 const locate=()=>new Promise<{lat:number;lng:number}>((resolve,rejectPromise)=>{if(!navigator.geolocation)return rejectPromise(new Error('Este dispositivo não oferece geolocalização.'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>rejectPromise(new Error('Permita o acesso à localização do aparelho.')),{enableHighAccuracy:true,timeout:12000,maximumAge:0});});
 const captureGps=async()=>{try{const pos=await locate();setGps(pos);if(vehicle)await post(`/vehicles/${vehicle.id}/location`,{...pos,label:'Posição capturada pelo aplicativo do motorista'});onToast('Localização atualizada.');}catch(err){onToast(err instanceof Error?err.message:'Falha de GPS.');}};
 const confirm=async(e:React.FormEvent)=>{e.preventDefault();if(!target)return;if(!signature){onToast('Colete a assinatura do recebedor.');return;}setBusy(true);let targetId=target.id;const clientEventId=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;try{const pos=await locate();const payload={clientEventId,receiverName:receiver,receiverDoc:doc,signature,lat:pos.lat,lng:pos.lng,deliveryMode:mode,rejectedWeightKg:Number(reject)||0,rejectionPhoto:photo||undefined};const result=await post<{orders:Order[];vehicles:Vehicle[]}>('/deliveries/'+targetId+'/confirm',payload);await onRefresh();setTarget(null);setSignature('');setGps(pos);onToast(`Entrega registrada: ${result.orders.find(o=>o.id===targetId)?.tradeName}.`);}catch(err){if(!navigator.onLine||err instanceof TypeError){try{const pos=gps||await locate();const payload={clientEventId,receiverName:receiver,receiverDoc:doc,signature,lat:pos.lat,lng:pos.lng,deliveryMode:mode,rejectedWeightKg:Number(reject)||0,rejectionPhoto:photo||undefined};await enqueueMutation({path:'/deliveries/'+targetId+'/confirm',method:'POST',body:payload});setQueuedIds(prev=>[...new Set([...prev,targetId])]);setQueuedCount(await queuedMutationCount());setTarget(null);setSignature('');onToast('Entrega salva neste aparelho. A baixa será sincronizada quando a conexão voltar.');}catch(queueError){onToast(queueError instanceof Error?queueError.message:'Não foi possível guardar a entrega offline.');}}else onToast(err instanceof Error?err.message:'Falha na confirmação.');}finally{setBusy(false);}};
 const report=(o:Order)=>{setOccurrenceTarget(o);setOccurrenceReason('');setOccurrencePhoto('');};
 const submitOccurrence=async(e:React.FormEvent)=>{e.preventDefault();if(!occurrenceTarget||!occurrenceReason||!occurrencePhoto){onToast('Informe o motivo e anexe uma foto da ocorrência.');return;}setBusy(true);const id=occurrenceTarget.id;const clientEventId=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;try{const pos=await locate();await post(`/deliveries/${id}/occurrence`,{clientEventId,reason:occurrenceReason,photo:occurrencePhoto,lat:pos.lat,lng:pos.lng});await onRefresh();setOccurrenceTarget(null);onToast('Ocorrência registrada com foto e GPS.');}catch(err){if(!navigator.onLine||err instanceof TypeError){try{const pos=gps||await locate();await enqueueMutation({path:`/deliveries/${id}/occurrence`,method:'POST',body:{clientEventId,reason:occurrenceReason,photo:occurrencePhoto,lat:pos.lat,lng:pos.lng}});setQueuedIds(prev=>[...new Set([...prev,id])]);setQueuedCount(await queuedMutationCount());setOccurrenceTarget(null);onToast('Ocorrência guardada neste aparelho para sincronização.');}catch(queueError){onToast(queueError instanceof Error?queueError.message:'Não foi possível guardar a ocorrência offline.');}}else onToast(err instanceof Error?err.message:'Falha ao registrar ocorrência.');}finally{setBusy(false);}};
 const currentStop=assigned.find(o=>o.status==='em_rota');
 const invoiceSignature=assigned.filter(o=>o.nfePdfAvailable).map(o=>`${o.id}:${o.nfePdfUploadedAt||''}`).join('|');
 React.useEffect(()=>{const online=()=>setIsOnline(true);const offline=()=>setIsOnline(false);window.addEventListener('online',online);window.addEventListener('offline',offline);return()=>{window.removeEventListener('online',online);window.removeEventListener('offline',offline);};},[]);
 React.useEffect(()=>{let cancelled=false;const preload=async()=>{try{const keys=await listOfflineDocumentKeys();if(cancelled)return;const routeKeys=keys.filter(key=>assigned.some(order=>order.id===key));setInvoiceStates(prev=>({...prev,...Object.fromEntries(routeKeys.map(key=>[key,'ready' as const]))}));if(!navigator.onLine)return;for(const order of assigned.filter(o=>o.nfePdfAvailable)){if(cancelled)break;setInvoiceStates(prev=>({...prev,[order.id]:'syncing'}));try{const response=await fetch(`/api/orders/${encodeURIComponent(order.id)}/invoice-pdf`,{credentials:'include'});if(!response.ok)throw new Error('PDF indisponível');const blob=await response.blob();await saveOfflineDocument(order.id,blob,order.nfePdfFilename||`NFe-${order.nfe||order.id}.pdf`);if(!cancelled)setInvoiceStates(prev=>({...prev,[order.id]:'ready'}));}catch{if(!cancelled)setInvoiceStates(prev=>({...prev,[order.id]:'missing'}));}}}catch{/* IndexedDB pode estar desabilitado no navegador */}};preload();return()=>{cancelled=true;};},[invoiceSignature]);
 const openInvoice=async(order:Order)=>{const tab=window.open('about:blank','_blank');try{let saved=await readOfflineDocument(order.id);if(navigator.onLine&&order.nfePdfAvailable){try{const response=await fetch(`/api/orders/${encodeURIComponent(order.id)}/invoice-pdf`,{credentials:'include'});if(response.ok){const blob=await response.blob();await saveOfflineDocument(order.id,blob,order.nfePdfFilename||`NFe-${order.nfe||order.id}.pdf`);saved={key:order.id,blob,filename:order.nfePdfFilename||`NFe-${order.nfe||order.id}.pdf`,contentType:'application/pdf',cachedAt:new Date().toISOString()};setInvoiceStates(prev=>({...prev,[order.id]:'ready'}));}}catch{/* usa cópia local */}}if(!saved){tab?.close();onToast(order.nfePdfAvailable?'NF-e ainda não foi sincronizada para uso offline.':'PDF da NF-e ainda não foi anexado pela central.');return;}const url=URL.createObjectURL(saved.blob);if(tab)tab.location.href=url;else{const link=document.createElement('a');link.href=url;link.download=saved.filename;link.click();}window.setTimeout(()=>URL.revokeObjectURL(url),60000);}catch{tab?.close();onToast('Não foi possível abrir o PDF desta NF-e.');}};
 const googleRouteUrl=()=>{const stops=assigned.filter(o=>o.status!=='entregue'&&o.status!=='entregue_parcial').sort((a,b)=>(a.lifoPosition||99)-(b.lifoPosition||99));if(!stops.length)return 'https://www.google.com/maps';const destination=`${stops[stops.length-1].address}, ${stops[stops.length-1].city||'Salvador'}`;const waypoints=stops.slice(0,-1).map(o=>`${o.address}, ${o.city||'Salvador'}`).slice(0,9).join('|');return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}${waypoints?`&waypoints=${encodeURIComponent(waypoints)}`:''}&travelmode=driving`;};
 const googleStopUrl=(o:Order)=>`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${o.address}, ${o.neighborhood||''}, ${o.city||'Salvador'}`)}&travelmode=driving`;
 const wazeStopUrl=(o:Order)=>o.lat!=null&&o.lng!=null?`https://waze.com/ul?ll=${encodeURIComponent(`${o.lat},${o.lng}`)}&navigate=yes`:`https://waze.com/ul?q=${encodeURIComponent(`${o.address}, ${o.neighborhood||''}, ${o.city||'Salvador'}`)}&navigate=yes`;
 const communicationFeed=[...communications,...localMessages].reduce((acc,msg)=>{const key=msg.clientEventId||msg.id;if(!acc.some(existing=>(existing.clientEventId||existing.id)===key))acc.push(msg);return acc;},[] as CommunicationMessage[]).slice(-8).reverse();
 const sendCommunication=async(kind:string,message:string,orderId?:string)=>{
   if(!message.trim())return;
   if(!vehicle?.activeRouteId){onToast('Nenhuma rota ativa para enviar a atualização.');return;}
   const clientEventId=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
   const payload={clientEventId,routeId:vehicle.activeRouteId,orderId:orderId||currentStop?.id||undefined,kind,message:message.trim()};
   setBusy(true);
   try{
     const saved=await post<CommunicationMessage>('/communications',payload);
     setLocalMessages(prev=>[...prev,saved]);
     onToast('Atualização enviada para a central.');
   }catch(err){
     if(!navigator.onLine||err instanceof TypeError){
       try{
         await enqueueMutation({path:'/communications',method:'POST',body:payload});
         const queued:CommunicationMessage={id:`offline-${clientEventId}`,clientEventId,routeId:payload.routeId,orderId:payload.orderId||null,senderId:user.id,senderName:user.name,senderRole:user.role,kind,message:payload.message,createdAt:new Date().toISOString()};
         setLocalMessages(prev=>[...prev,queued]);setQueuedCount(await queuedMutationCount());
         onToast('Salvo neste aparelho. A central receberá quando a conexão voltar.');
       }catch(queueError){onToast(queueError instanceof Error?queueError.message:'Não foi possível salvar a mensagem offline.');}
     }else onToast(err instanceof Error?err.message:'Falha ao enviar atualização.');
   }finally{setBusy(false);}
 };
 const sendText=async(e:React.FormEvent)=>{e.preventDefault();if(!quickText.trim())return;const message=quickText;setQuickText('');await sendCommunication('text',message,currentStop?.id);};
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">APLICATIVO DO MOTORISTA</span><h1>Minha rota</h1><p>Romaneio, endereços, navegação e baixa digital de entrega.</p></div><div className="lm-inline-actions">{assigned.some(o=>o.status==='em_rota')&&<a className="lm-secondary-button" href={googleRouteUrl()} target="_blank" rel="noreferrer"><MapPinned size={15}/> Rota completa · Maps</a>}<button className="lm-secondary-button" onClick={captureGps}><MapPin size={15}/> Capturar GPS</button></div></div><div className="lm-driver-hero"><div className="lm-driver-avatar">{user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><span>MOTORISTA CONECTADO</span><h2>{user.name}</h2><p>{vehicle?`${vehicle.name} · ${vehicle.plate}`:'Nenhum veículo associado ao usuário'}</p></div><div className="lm-driver-gps"><i/>{gps?`${gps.lat.toFixed(5)}, ${gps.lng.toFixed(5)}`:'GPS não capturado'}</div></div><div className="lm-driver-summary"><div><b>{assigned.filter(o=>o.status==='em_rota').length}</b><span>paradas a concluir</span></div><div><b>{assigned.filter(o=>['entregue','entregue_parcial'].includes(o.status)).length}</b><span>entregas baixadas</span></div><div><b>{number(vehicle?.currentWeightKg||0)} kg</b><span>peso no veículo</span></div><div><b>{number(vehicle?.currentVolumeM3||0)} m³</b><span>cubagem no veículo</span></div></div><section className="lm-panel lm-driver-comms"><div className="lm-panel-heading"><div><span className="lm-eyebrow">CANAL DIRETO COM A CENTRAL</span><h3>Confirmação rápida</h3><p>Atualize a equipe sem precisar abrir uma ocorrência formal.</p></div><span className={`lm-network-state ${isOnline?'is-online':'is-offline'}`}>{isOnline?<><Wifi size={13}/> Online</>:<><WifiOff size={13}/> Offline · fila local ativa</>}</span></div><div className="lm-pwa-doc-notice"><FileText size={15}/><span>As NFs em PDF desta rota são sincronizadas para consulta offline quando anexadas pela central.</span><b>{assigned.filter(o=>o.nfePdfAvailable&&invoiceStates[o.id]==='ready').length}/{assigned.filter(o=>o.nfePdfAvailable).length} PDFs offline</b></div><div className="lm-quick-confirm-actions"><button type="button" onClick={()=>sendCommunication('arrived','Cheguei ao cliente.',currentStop?.id)} disabled={busy||!currentStop}><MapPin size={16}/> Cheguei</button><button type="button" onClick={()=>sendCommunication('waiting','Aguardando descarga / atendimento.',currentStop?.id)} disabled={busy||!currentStop}><Clock3 size={16}/> Aguardando</button><button type="button" onClick={()=>sendCommunication('help','Preciso de ajuda da central.',currentStop?.id)} disabled={busy||!vehicle?.activeRouteId}><AlertTriangle size={16}/> Preciso de ajuda</button><button type="button" onClick={()=>sendCommunication('next_stop','Seguindo para a próxima parada.',currentStop?.id)} disabled={busy||!vehicle?.activeRouteId}><Navigation size={16}/> Próxima parada</button></div><form className="lm-driver-message-form" onSubmit={sendText}><input value={quickText} onChange={e=>setQuickText(e.target.value)} placeholder="Mensagem rápida para a central…" maxLength={500}/><button className="lm-primary-button" disabled={busy||!quickText.trim()}><Send size={15}/> Enviar</button></form>{communicationFeed.length>0&&<div className="lm-message-feed lm-message-feed-driver">{communicationFeed.slice(0,4).map(m=><div key={m.clientEventId||m.id} className={`lm-message-item ${m.senderRole==='DRIVER'?'from-driver':'from-central'}`}><div><b>{m.senderName}</b><small>{new Date(m.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div><p>{m.message}</p></div>)}</div>}</section><section className="lm-panel lm-driver-stops">{queuedCount>0&&<div className="lm-offline-banner"><Activity size={15}/>{queuedCount} ação(ões) pendente(s) de sincronização. Mantenha o app aberto ou reconecte à internet.</div>}<div className="lm-panel-heading"><div><span className="lm-eyebrow">SEQUÊNCIA DE DESCARGA · LIFO</span><h3>Paradas do dia</h3></div><span className="lm-subtle-tag">A primeira parada fica junto à porta</span></div>{assigned.map((o,i)=><div className="lm-driver-stop" key={o.id}><div className="lm-stop-number">{o.lifoPosition||i+1}</div><div className="lm-stop-details"><div><b>{o.tradeName}</b>{queuedIds.includes(o.id)?<span className="lm-status is-warning"><i/>Aguardando sincronização</span>:<Status status={o.status}/>}</div><p><MapPin size={13}/>{o.address} · {o.neighborhood}</p><small>NF-e {o.nfe||'—'} · {o.timeWindow} · {number(o.weightKg)} kg</small></div><div className="lm-stop-actions lm-stop-actions-rich">{o.nfePdfAvailable?<button className="lm-small-button" onClick={()=>openInvoice(o)} title="Abrir NF-e em PDF, inclusive sem internet"><FileText size={13}/>{invoiceStates[o.id]==='syncing'?'Baixando PDF':invoiceStates[o.id]==='ready'?'NF-e offline':'Abrir NF-e PDF'}</button>:<span className="lm-pwa-pdf-missing" title="A central precisa anexar o PDF oficial da DANFE">PDF não anexado</span>}{o.status==='em_rota'&&!queuedIds.includes(o.id)&&<><a href={wazeStopUrl(o)} target="_blank" rel="noreferrer" className="lm-small-button"><Navigation size={13}/> Waze</a><a href={googleStopUrl(o)} target="_blank" rel="noreferrer" className="lm-small-button"><MapPinned size={13}/> Maps</a><button className="lm-small-button lm-small-green" onClick={()=>{setTarget(o);setReceiver('');setDoc('');setSignature('');setMode('integral');setReject('');setPhoto('');}}>Baixar entrega</button><button className="lm-small-button lm-small-danger" onClick={()=>report(o)} disabled={busy}>Ocorrência</button></>}{(o.status==='entregue'||queuedIds.includes(o.id))&&<span className="lm-done-label"><CheckCircle2 size={15}/> {queuedIds.includes(o.id)?'Sincronização pendente':'Concluída'}</span>}</div></div>)}{!assigned.length&&<div className="lm-empty-inline"><Truck size={19}/>Nenhuma rota atribuída a este motorista no momento.</div>}</section>
 {target&&<div className="lm-modal-backdrop"><form className="lm-modal" onSubmit={confirm}><div className="lm-modal-head"><div><span className="lm-eyebrow">BAIXA DIGITAL</span><h2>Confirmar entrega</h2><p>{target.tradeName} · NF {target.nfe}</p></div><button type="button" className="lm-icon-button" onClick={()=>setTarget(null)}><X/></button></div><div className="lm-gps-box"><MapPin size={16}/><span>A localização será registrada. Para ocorrências, distância acima do raio configurado gera aviso, mas não impede o envio à central.</span></div><div className="lm-form-grid"><Field label="Nome do recebedor" value={receiver} onChange={setReceiver} required/><Field label="Documento (CPF/RG)" value={doc} onChange={setDoc} required/><label className="lm-field"><span>Tipo de baixa</span><select value={mode} onChange={e=>setMode(e.target.value)}><option value="integral">Entrega integral</option><option value="parcial">Entrega parcial</option></select></label>{mode==='parcial'&&<Field label="Peso recusado (kg)" type="number" value={reject} onChange={setReject} required/>}</div>{mode==='parcial'&&<label className="lm-field"><span>Foto de evidência (arquivo)</span><input type="file" accept="image/*" onChange={async e=>{const f=e.target.files?.[0];if(f){const reader=new FileReader();reader.onload=()=>setPhoto(String(reader.result||''));reader.readAsDataURL(f);}}}/></label>}<label className="lm-field"><span>Assinatura do recebedor</span><Signature onChange={setSignature}/></label><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setTarget(null)}>Cancelar</button><button className="lm-primary-button" disabled={busy}>{busy?'Validando GPS…':'Confirmar e baixar pedido'}</button></div></form></div>}
 {occurrenceTarget&&<div className="lm-modal-backdrop"><form className="lm-modal" onSubmit={submitOccurrence}><div className="lm-modal-head"><div><span className="lm-eyebrow">REGISTRO DE EXCEÇÃO</span><h2>Informar ocorrência</h2><p>{occurrenceTarget.tradeName} · NF {occurrenceTarget.nfe||'—'}</p></div><button type="button" className="lm-icon-button" onClick={()=>setOccurrenceTarget(null)}><X/></button></div><label className="lm-field"><span>Motivo</span><select value={occurrenceReason} onChange={e=>setOccurrenceReason(e.target.value)} required><option value="">Selecione o motivo</option><option>Estabelecimento fechado</option><option>Recusa total</option><option>Endereço não localizado</option><option>Mercadoria avariada</option><option>Outro</option></select></label><label className="lm-field"><span>Foto obrigatória da fachada ou mercadoria</span><input type="file" accept="image/*" required onChange={async e=>{const f=e.target.files?.[0];if(f){const reader=new FileReader();reader.onload=()=>setOccurrencePhoto(String(reader.result||''));reader.readAsDataURL(f);}}}/></label><div className="lm-gps-box"><MapPin size={16}/><span>A localização atual será anexada como evidência da ocorrência.</span></div><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setOccurrenceTarget(null)}>Cancelar</button><button className="lm-primary-button" disabled={busy||!occurrencePhoto}>{busy?'Registrando…':'Registrar ocorrência'}</button></div></form></div>}
 </div>;
}

export function UsersView({users,onRefresh,onToast,currentUser}:{users:any[];onRefresh:()=>Promise<void>;onToast:(s:string)=>void;currentUser:User}) {
 const [show,setShow]=useState(false);const [form,setForm]=useState({name:'',email:'',role:'DISPATCHER',password:''});const [busy,setBusy]=useState(false);
 const create=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await post('/users',form);await onRefresh();setShow(false);setForm({name:'',email:'',role:'DISPATCHER',password:''});onToast('Usuário criado com sucesso.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao criar usuário.');}finally{setBusy(false);}};
 const toggle=async(u:any)=>{try{await patch(`/users/${u.id}`,{active:!u.active});await onRefresh();onToast('Acesso atualizado.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao atualizar usuário.');}};
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">SEGURANÇA E PERMISSÕES</span><h1>Usuários e acessos</h1><p>Controle quem acessa o painel e quais ações cada perfil pode executar.</p></div><button className="lm-primary-button" onClick={()=>setShow(true)}><Plus size={16}/> Novo usuário</button></div><div className="lm-user-grid">{users.map(u=><div key={u.id} className="lm-panel lm-user-card"><div className="lm-user-avatar">{u.name.split(' ').map((s:string)=>s[0]).slice(0,2).join('')}</div><div className="lm-user-detail"><b>{u.name}</b><span>{u.email}</span><small>{roleName[u.role]||u.role}</small></div><span className={`lm-access-badge ${u.active?'':'is-off'}`}>{u.active?'Ativo':'Inativo'}</span><button className="lm-small-button" disabled={u.id===currentUser.id} onClick={()=>toggle(u)}>{u.active?'Desativar':'Ativar'}</button></div>)}</div>{show&&<div className="lm-modal-backdrop"><form className="lm-modal" onSubmit={create}><div className="lm-modal-head"><div><span className="lm-eyebrow">NOVO ACESSO</span><h2>Cadastrar usuário</h2></div><button type="button" className="lm-icon-button" onClick={()=>setShow(false)}><X/></button></div><div className="lm-form-grid"><Field label="Nome completo" value={form.name} onChange={v=>setForm({...form,name:v})} required wide/><Field label="E-mail corporativo" type="email" value={form.email} onChange={v=>setForm({...form,email:v})} required wide/><label className="lm-field lm-field-wide"><span>Perfil de acesso</span><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="MANAGER">Gestor / Proprietário</option><option value="DISPATCHER">Despachante</option><option value="DRIVER">Motorista</option><option value="SALES_REP">Vendedor</option></select></label><Field label="Senha inicial (mín. 8 caracteres)" value={form.password} onChange={v=>setForm({...form,password:v})} required wide/></div><div className="lm-modal-actions"><button type="button" className="lm-secondary-button" onClick={()=>setShow(false)}>Cancelar</button><button className="lm-primary-button" disabled={busy}>{busy?'Criando…':'Criar usuário'}</button></div></form></div>}</div>;
}

export function SettingsView({config,user,onSave,onToast}:{config:Config;user:User;onSave:(c:Config)=>Promise<void>;onToast:(s:string)=>void}) {
 const [form,setForm]=useState<Config>(config);const [busy,setBusy]=useState(false);
 React.useEffect(()=>setForm(config),[config]);
 const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await onSave(form);onToast('Parâmetros atualizados.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao salvar parâmetros.');}finally{setBusy(false);}};
 const cost=(form.redeliveryDistanceKm/form.avgFuelEfficiencyKmL)*form.dieselPricePerLiter+form.redeliveryFixedTimeHours*form.crewHourlyRate;
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">PARAMETRIZAÇÃO OPERACIONAL</span><h1>Configurações</h1><p>Defina limites físicos e variáveis para os cálculos determinísticos.</p></div></div><form onSubmit={save} className="lm-settings-grid"><section className="lm-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">CUSTOS DE OPERAÇÃO</span><h3>Parâmetros de reentrega</h3></div><Fuel size={18}/></div><div className="lm-settings-fields"><Field label="Diesel por litro (R$)" type="number" value={String(form.dieselPricePerLiter)} onChange={v=>setForm({...form,dieselPricePerLiter:Number(v)})}/><Field label="Custo da equipe por hora (R$)" type="number" value={String(form.crewHourlyRate)} onChange={v=>setForm({...form,crewHourlyRate:Number(v)})}/><Field label="Distância adicional de reentrega (km)" type="number" value={String(form.redeliveryDistanceKm)} onChange={v=>setForm({...form,redeliveryDistanceKm:Number(v)})}/><Field label="Consumo médio (km/L)" type="number" value={String(form.avgFuelEfficiencyKmL)} onChange={v=>setForm({...form,avgFuelEfficiencyKmL:Number(v)})}/><Field label="Tempo adicional por reentrega (h)" type="number" value={String(form.redeliveryFixedTimeHours)} onChange={v=>setForm({...form,redeliveryFixedTimeHours:Number(v)})}/><Field label="Custo de reprocessamento (R$)" type="number" value={String(form.reverseProcessingCost)} onChange={v=>setForm({...form,reverseProcessingCost:Number(v)})}/></div><div className="lm-calculation-result"><span>Custo operacional estimado por reentrega</span><b>{brl(cost)}</b><small>(distância ÷ consumo × diesel) + (tempo × custo da equipe)</small></div></section><section className="lm-panel"><div className="lm-panel-heading"><div><span className="lm-eyebrow">REGRAS DE EXECUÇÃO</span><h3>Limites e tolerâncias</h3></div><ShieldAlert size={18}/></div><div className="lm-settings-fields"><Field label="Margem operacional mínima (%)" type="number" value={String(form.minProfitMarginPct)} onChange={v=>setForm({...form,minProfitMarginPct:Number(v)})}/><Field label="Ocupação máxima de projeto (%)" type="number" value={String(form.maxVehicleUtilizationPct)} onChange={v=>setForm({...form,maxVehicleUtilizationPct:Number(v)})}/><Field label="Raio de geofence (metros)" type="number" value={String(form.geofenceRadiusMeters)} onChange={v=>setForm({...form,geofenceRadiusMeters:Number(v)})}/><Field label="Gatilho de atraso (minutos)" type="number" value={String(form.trafficDelayThresholdMinutes)} onChange={v=>setForm({...form,trafficDelayThresholdMinutes:Number(v)})}/><Field label="Tempo padrão de descarga (min)" type="number" value={String(form.defaultUnloadMinutes)} onChange={v=>setForm({...form,defaultUnloadMinutes:Number(v)})}/><Field label="Janela offline do motorista (h)" type="number" value={String(form.offlineWindowHours)} onChange={v=>setForm({...form,offlineWindowHours:Number(v)})}/></div><div className="lm-form-helper">As regras de capacidade, FEFO, LIFO e geofence são executadas por código determinístico. IA generativa não participa dos cálculos.</div></section><div className="lm-settings-save"><button className="lm-primary-button" disabled={busy}>{busy?'Salvando…':'Salvar configurações'}</button></div></form><PasswordChangeCard onToast={onToast}/></div>;
}

function PasswordChangeCard({onToast}:{onToast:(s:string)=>void}) {
 const [currentPassword,setCurrentPassword]=useState('');const [newPassword,setNewPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [busy,setBusy]=useState(false);
 const submit=async(e:React.FormEvent)=>{e.preventDefault();if(newPassword!==confirmPassword){onToast('A confirmação de senha não confere.');return;}setBusy(true);try{await post('/auth/change-password',{currentPassword,newPassword});setCurrentPassword('');setNewPassword('');setConfirmPassword('');onToast('Senha alterada. As outras sessões foram encerradas.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao alterar a senha.');}finally{setBusy(false);}};
 return <form className="lm-panel lm-password-card" onSubmit={submit}><div className="lm-panel-heading"><div><span className="lm-eyebrow">SEGURANÇA DA CONTA</span><h3>Alterar senha</h3></div><ShieldAlert size={18}/></div><div className="lm-settings-fields"><Field label="Senha atual" type="password" value={currentPassword} onChange={setCurrentPassword} required/><Field label="Nova senha (mín. 8 caracteres)" type="password" value={newPassword} onChange={setNewPassword} required/><Field label="Confirmar nova senha" type="password" value={confirmPassword} onChange={setConfirmPassword} required/></div><div className="lm-settings-save"><button className="lm-primary-button" disabled={busy}>{busy?'Atualizando…':'Alterar senha'}</button></div></form>;
}

export function IntegrationsView({onToast}:{onToast:(s:string)=>void}) {
 const [keys,setKeys]=useState<any[]>([]);const [wa,setWa]=useState<any>({configured:false,webhookConfigured:false});const [label,setLabel]=useState('ERP / Sistema de vendas');const [newToken,setNewToken]=useState('');const [loading,setLoading]=useState(false);const [waTo,setWaTo]=useState('');const [waMessage,setWaMessage]=useState('');
 const refresh=async()=>{try{const [k,w]=await Promise.all([api<any[]>('/integrations/api-keys'),api('/integrations/whatsapp/status')]);setKeys(k);setWa(w);}catch(err){onToast(err instanceof Error?err.message:'Não foi possível carregar integrações.');}};
 React.useEffect(()=>{refresh();},[]);
 const createKey=async()=>{setLoading(true);try{const result=await post<any>('/integrations/api-keys',{label});setNewToken(result.token);await refresh();onToast('API key criada. Copie o segredo antes de fechar a janela.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao gerar API key.');}finally{setLoading(false);}};
 const send=async()=>{setLoading(true);try{await post('/integrations/whatsapp/send',{to:waTo,message:waMessage});onToast('Mensagem aceita pela API do WhatsApp.');}catch(err){onToast(err instanceof Error?err.message:'Falha no envio do WhatsApp.');}finally{setLoading(false);}};
 const copy=(v:string)=>navigator.clipboard?.writeText(v).then(()=>onToast('Copiado para a área de transferência.')).catch(()=>onToast('Não foi possível copiar automaticamente.'));
 const revoke=async(id:string)=>{try{await api(`/integrations/api-keys/${id}`,{method:'DELETE'});await refresh();onToast('Chave revogada.');}catch(err){onToast(err instanceof Error?err.message:'Falha ao revogar.');}};
 return <div className="lm-page-stack"><div className="lm-page-heading"><div><span className="lm-eyebrow">CONECTIVIDADE E ENTRADA DE DADOS</span><h1>Integrações</h1><p>Conecte plataformas de venda e logística sem duplicar o trabalho da operação.</p></div></div><div className="lm-integrations-grid"><section className="lm-panel"><div className="lm-integration-head"><div className="lm-integration-logo lm-api-logo"><FileCode2Icon/></div><div><span className="lm-eyebrow">API REST</span><h3>ERP, vendas e logística</h3><p>Receba pedidos automaticamente de sistemas externos.</p></div><span className="lm-connection-state is-ready">Disponível</span></div><div className="lm-endpoint-card"><small>ENDPOINT DE ENTRADA</small><code>POST /api/integrations/orders</code><small>Cabeçalho: <code>X-API-Key</code> · Payload JSON com cliente, endereço, peso, cubagem e itens.</small></div><div className="lm-key-create"><input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Identificação da integração"/><button className="lm-primary-button" onClick={createKey} disabled={loading}><Plus size={15}/> Gerar API key</button></div>{newToken&&<div className="lm-token-reveal"><b>Copie seu token agora — ele não será exibido novamente</b><div><code>{newToken}</code><button onClick={()=>copy(newToken)}>Copiar</button></div></div>}<div className="lm-key-list">{keys.map(k=><div key={k.id}><span><b>{k.label}</b><small>{k.token_prefix}•••• · criada em {new Date(k.created_at).toLocaleDateString('pt-BR')}</small></span><button className="lm-small-button lm-small-danger" onClick={()=>revoke(k.id)}>Revogar</button></div>)}</div></section>
 <section className="lm-panel"><div className="lm-integration-head"><div className="lm-integration-logo lm-whatsapp-logo">W</div><div><span className="lm-eyebrow">META CLOUD API</span><h3>WhatsApp Business</h3><p>Notificações preventivas de atraso e recebimento de pedidos por webhook.</p></div><span className={`lm-connection-state ${wa.configured?'is-ready':'is-pending'}`}>{wa.configured?'Conectado':'Credenciais pendentes'}</span></div><div className="lm-wa-status"><div><span>Envio de mensagens</span><b>{wa.configured?'Configurado no servidor':'Aguardando credenciais'}</b></div><div><span>Webhook de entrada</span><b>{wa.webhookConfigured?'Verificação configurada':'Token de verificação pendente'}</b></div></div><div className="lm-form-helper">Configure no servidor: <code>WHATSAPP_ACCESS_TOKEN</code>, <code>WHATSAPP_PHONE_NUMBER_ID</code>, <code>WHATSAPP_API_VERSION</code> e <code>WHATSAPP_VERIFY_TOKEN</code>. Os segredos não ficam expostos no navegador.</div><div className="lm-wa-test"><b>Teste de mensagem</b><Field label="WhatsApp do destinatário (com DDI)" value={waTo} onChange={setWaTo}/><label className="lm-field"><span>Mensagem</span><textarea rows={3} value={waMessage} onChange={e=>setWaMessage(e.target.value)} placeholder="Sua entrega está prevista para…"/></label><button className="lm-secondary-button" disabled={loading||!waTo||!waMessage} onClick={send}>Enviar teste <ArrowRight size={14}/></button></div></section></div><div className="lm-import-note"><FileSpreadsheet size={17}/><div><b>Integração sem desenvolvimento complexo</b><span>Para operação inicial, use importação CSV, JSON ou XML de NF-e. Para automação, entregue a API key ao fornecedor do ERP e envie o pedido normalizado. Pedidos com dados críticos faltando entram na quarentena.</span></div></div></div>;
}
function FileCode2Icon(){return <span className="lm-code-glyph">{`</>`}</span>}
